diagram:
graph TD;
    A[Parent Class] --> B[Child Class (extends Parent)];
    B --> C[Grandchild Class (extends Child)];
    style A fill:#f9f,stroke:#333,stroke-width:2px;
    style B fill:#bbf,stroke:#333,stroke-width:2px;
    style C fill:#9f9,stroke:#333,stroke-width:2px;

graph TD;
    A[Code Execution] --> B{Potential Error?};
    B -- Yes --> C[try Block];
    C --> D[Problem Occurs];
    D -- Throws Exception --> E[catch Block];
    E --> F[Handle Exception];
    F --> G[finally Block (optional)];
    G --> H[Continue Program];
    B -- No --> I[Normal Execution];
    I --> G;

graph TD;
    A[User Action (e.g., Click)] --> B[GUI Component (Event Source)];
    B -- Generates Event Object --> C[Event Listener Interface];
    C -- Invokes Handler Method --> D[Listener Implementation];
    D --> E[Perform Action];

graph TD;
    A[Java Application] --> B[Load JDBC Driver];
    B --> C[Establish Connection];
    C --> D[Create Statement];
    D --> E[Execute SQL Query];
    E --> F{Query Type?};
    F -- SELECT --> G[Process ResultSet];
    F -- DML/DDL --> H[Get Update Count];
    G --> I[Close Resources];
    H --> I;
    I --> J[End Interaction];
